SELECT DISTINCT md.chembl_id AS chembl_id, md.pref_name AS pref_name, cs.canonical_smiles AS canonical_smiles, di.efo_id AS indication_curie, di.efo_term AS indication_label, di.max_phase_for_ind AS max_phase_for_ind FROM molecule_dictionary md INNER JOIN drug_indication di ON md.molregno = di.molregno INNER JOIN compound_structures cs ON md.molregno = cs.molregno WHERE di.max_phase_for_ind = 4 AND di.efo_term = 'breast cancer' ORDER BY chembl_id, pref_name, canonical_smiles, indication_curie, indication_label, max_phase_for_ind
